package com.farmnotifier;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("farmnotifier")
public interface FarmNotifierConfig extends Config
{
    // -------------------------------------------------------------------------
    // Sections
    // -------------------------------------------------------------------------

    @ConfigSection(
            name = "Discord",
            description = "Settings for Discord notifications",
            position = 0
    )
    String discordSection = "discord";

    @ConfigSection(
            name = "Notifications",
            description = "When and how to send notifications",
            position = 1
    )
    String notifySection = "notifications";

    // -------------------------------------------------------------------------
    // Discord settings
    // -------------------------------------------------------------------------

    @ConfigItem(
            keyName = "webhookUrl",
            name = "Webhook URL",
            description = "Your Discord channel webhook URL. "
                    + "Create one in: Channel Settings → Integrations → Webhooks → New Webhook.",
            section = discordSection,
            position = 0,
            secret = true
    )
    default String webhookUrl()
    {
        return "";
    }

    @ConfigItem(
            keyName = "discordUserId",
            name = "Your Discord User ID",
            description = "Your Discord user ID for @mention pings. "
                    + "Enable Developer Mode (Settings → Advanced), then right-click your name → Copy User ID.",
            section = discordSection,
            position = 1
    )
    default String discordUserId()
    {
        return "";
    }

    @ConfigItem(
            keyName = "sendTestMessage",
            name = "Send test message",
            description = "Toggle on then off to fire a test webhook and confirm everything is connected.",
            section = discordSection,
            position = 2
    )
    default boolean sendTestMessage()
    {
        return false;
    }

    // -------------------------------------------------------------------------
    // Notification settings
    // -------------------------------------------------------------------------

    @ConfigItem(
            keyName = "notifyOnlyWhenLoggedOut",
            name = "Only notify when offline",
            description = "If enabled, in-client notifications are suppressed while you are logged in. "
                    + "Cloud notifications always fire regardless.",
            section = notifySection,
            position = 0
    )
    default boolean notifyOnlyWhenLoggedOut()
    {
        return false;
    }

    @ConfigItem(
            keyName = "sendScreenshotOnPlant",
            name = "Send screenshot when planting",
            description = "Attaches a screenshot of your game to the Discord message when a patch is planted.",
            section = notifySection,
            position = 1
    )
    default boolean sendScreenshotOnPlant()
    {
        return true;
    }

    @ConfigItem(
            keyName = "notifyBeforeReady",
            name = "Notify before patch is ready",
            description = "Send an early warning notification X minutes before a patch finishes growing.",
            section = notifySection,
            position = 2
    )
    default boolean notifyBeforeReady()
    {
        return false;
    }

    @Range(min = 1, max = 120)
    @ConfigItem(
            keyName = "minutesBefore",
            name = "Minutes before ready",
            description = "How many minutes before the patch is ready to send the early warning. "
                    + "Only used if 'Notify before patch is ready' is enabled.",
            section = notifySection,
            position = 3
    )
    default int minutesBefore()
    {
        return 10;
    }
}

package com.farmnotifier;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class FarmNotifierPanel extends PluginPanel
{
    private static final Color COLOR_READY      = new Color(0, 200, 80);
    private static final Color COLOR_GROWING    = new Color(200, 200, 200);
    private static final Color COLOR_DISEASED   = new Color(230, 160, 0);
    private static final Color COLOR_DEAD       = new Color(200, 50, 50);
    private static final Color COLOR_HEADER_BG  = new Color(40, 40, 40);
    private static final Color COLOR_ROW_BG     = new Color(50, 50, 50);
    private static final Color COLOR_ROW_ALT_BG = new Color(45, 45, 45);

    private final FarmNotifierPlugin plugin;
    private final FarmNotifierConfig config;

    /** Live countdown labels keyed by patchKey */
    private final Map<String, JLabel> countdownLabels = new LinkedHashMap<>();
    /** Health status labels keyed by patchKey */
    private final Map<String, JLabel> healthLabels = new LinkedHashMap<>();
    /** Start buttons keyed by patchKey */
    private final Map<String, JButton> startButtons = new LinkedHashMap<>();
    /** Reset buttons keyed by patchKey */
    private final Map<String, JButton> resetButtons = new LinkedHashMap<>();

    public FarmNotifierPanel(FarmNotifierPlugin plugin, FarmNotifierConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        add(buildHeader(), BorderLayout.NORTH);

        JPanel content = buildContent();
        JScrollPane scroll = new JScrollPane(content);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.getVerticalScrollBar().setUnitIncrement(8);
        add(scroll, BorderLayout.CENTER);
    }

    // -------------------------------------------------------------------------
    // Header
    // -------------------------------------------------------------------------

    private JPanel buildHeader()
    {
        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(COLOR_HEADER_BG);
        header.setBorder(new EmptyBorder(8, 8, 8, 8));

        JLabel title = new JLabel("Farm Run Notifier");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);
        header.add(title, BorderLayout.WEST);

        JLabel sub = new JLabel("Auto-tracking active patches");
        sub.setFont(FontManager.getRunescapeSmallFont());
        sub.setForeground(Color.GRAY);

        JPanel subPanel = new JPanel(new BorderLayout());
        subPanel.setBackground(COLOR_HEADER_BG);
        subPanel.setBorder(new EmptyBorder(4, 8, 4, 8));
        subPanel.add(sub, BorderLayout.WEST);

        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setBackground(COLOR_HEADER_BG);
        wrapper.add(header);
        wrapper.add(subPanel);
        return wrapper;
    }

    // -------------------------------------------------------------------------
    // Content (all patches, grouped by farm type)
    // -------------------------------------------------------------------------

    private JPanel buildContent()
    {
        JPanel outer = new JPanel();
        outer.setLayout(new BoxLayout(outer, BoxLayout.Y_AXIS));
        outer.setBackground(ColorScheme.DARK_GRAY_COLOR);

        FarmType lastType = null;
        int rowIndex = 0;

        for (FarmNotifierPlugin.PatchState ps : plugin.getPatchRegistry().values())
        {
            // Section header when farm type changes
            if (ps.farmType != lastType)
            {
                outer.add(buildSectionHeader(ps.farmType.getDisplayName()));
                lastType = ps.farmType;
                rowIndex = 0;
            }

            JPanel row = buildPatchRow(ps, rowIndex % 2 == 0);
            outer.add(row);
            rowIndex++;
        }

        // Padding at the bottom
        JPanel pad = new JPanel();
        pad.setBackground(ColorScheme.DARK_GRAY_COLOR);
        pad.setPreferredSize(new Dimension(1, 12));
        outer.add(pad);

        return outer;
    }

    private JPanel buildSectionHeader(String title)
    {
        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(new Color(35, 35, 35));
        header.setBorder(new EmptyBorder(6, 8, 4, 8));
        header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

        JLabel label = new JLabel(title.toUpperCase());
        label.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        label.setForeground(new Color(160, 130, 80));
        header.add(label, BorderLayout.WEST);
        return header;
    }

    private JPanel buildPatchRow(FarmNotifierPlugin.PatchState ps, boolean even)
    {
        JPanel row = new JPanel(new GridBagLayout());
        row.setBackground(even ? COLOR_ROW_BG : COLOR_ROW_ALT_BG);
        row.setBorder(new EmptyBorder(4, 8, 4, 8));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));

        GridBagConstraints c = new GridBagConstraints();
        c.insets = new Insets(1, 2, 1, 2);
        c.fill = GridBagConstraints.HORIZONTAL;

        // Patch name
        JLabel nameLabel = new JLabel(shortName(ps.displayName));
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setToolTipText(ps.displayName);
        c.gridx = 0; c.gridy = 0; c.weightx = 1.0;
        row.add(nameLabel, c);

        // Health label (same row, right side)
        JLabel healthLabel = new JLabel("");
        healthLabel.setFont(FontManager.getRunescapeSmallFont());
        healthLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        healthLabels.put(ps.patchKey, healthLabel);
        c.gridx = 1; c.gridy = 0; c.weightx = 0;
        row.add(healthLabel, c);

        // Countdown label
        JLabel countdown = new JLabel("Not started");
        countdown.setFont(FontManager.getRunescapeSmallFont());
        countdown.setForeground(Color.GRAY);
        countdownLabels.put(ps.patchKey, countdown);
        c.gridx = 0; c.gridy = 1; c.weightx = 1.0;
        row.add(countdown, c);

        // Buttons panel
        JPanel buttons = new JPanel();
        buttons.setOpaque(false);
        buttons.setLayout(new BoxLayout(buttons, BoxLayout.X_AXIS));

        JButton startBtn = smallButton("Start", new Color(60, 120, 60));
        startBtn.addActionListener(e -> plugin.startPatchTimer(ps));
        startButtons.put(ps.patchKey, startBtn);
        buttons.add(startBtn);

        JButton resetBtn = smallButton("Reset", new Color(120, 60, 60));
        resetBtn.addActionListener(e -> plugin.clearPatchTimer(ps, false));
        resetBtn.setEnabled(false);
        resetButtons.put(ps.patchKey, resetBtn);
        buttons.add(resetBtn);

        c.gridx = 1; c.gridy = 1; c.weightx = 0;
        row.add(buttons, c);

        return row;
    }

    // -------------------------------------------------------------------------
    // Refresh (called every second by the plugin)
    // -------------------------------------------------------------------------

    public void refresh()
    {
        long now = System.currentTimeMillis();

        for (FarmNotifierPlugin.PatchState ps : plugin.getPatchRegistry().values())
        {
            JLabel countdownLabel = countdownLabels.get(ps.patchKey);
            JLabel healthLabel    = healthLabels.get(ps.patchKey);
            JButton startBtn      = startButtons.get(ps.patchKey);
            JButton resetBtn      = resetButtons.get(ps.patchKey);

            if (countdownLabel == null) continue;

            if (!ps.isActive())
            {
                countdownLabel.setText("Not started");
                countdownLabel.setForeground(Color.GRAY);
                healthLabel.setText("");
                startBtn.setEnabled(true);
                resetBtn.setEnabled(false);
                continue;
            }

            // Health indicator
            switch (ps.health)
            {
                case DISEASED:
                    healthLabel.setText("🤒 Diseased");
                    healthLabel.setForeground(COLOR_DISEASED);
                    break;
                case DEAD:
                    healthLabel.setText("💀 Dead");
                    healthLabel.setForeground(COLOR_DEAD);
                    break;
                default:
                    healthLabel.setText("");
                    break;
            }

            if (now >= ps.readyAt)
            {
                countdownLabel.setText("✅ READY TO HARVEST");
                countdownLabel.setForeground(COLOR_READY);
            }
            else
            {
                long remaining = ps.readyAt - now;
                countdownLabel.setText(formatDuration(remaining));
                countdownLabel.setForeground(COLOR_GROWING);
            }

            startBtn.setEnabled(false);
            resetBtn.setEnabled(true);
        }
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private JButton smallButton(String text, Color bg)
    {
        JButton btn = new JButton(text);
        btn.setFont(FontManager.getRunescapeSmallFont());
        btn.setBackground(bg);
        btn.setForeground(Color.WHITE);
        btn.setFocusPainted(false);
        btn.setBorder(new EmptyBorder(2, 6, 2, 6));
        btn.setPreferredSize(new Dimension(48, 20));
        return btn;
    }

    /** Shorten long patch names so they fit in the panel. */
    private String shortName(String name)
    {
        return name.replace(" Patch", "")
                .replace(" Tree", "")
                .replace("Farming Guild", "F. Guild")
                .replace("Stronghold", "S'hold")
                .replace("Allotment", "Allot.");
    }

    private String formatDuration(long ms)
    {
        long totalSecs = ms / 1000;
        long hours = totalSecs / 3600;
        long mins  = (totalSecs % 3600) / 60;
        long secs  = totalSecs % 60;

        if (hours > 0)
        {
            return String.format("%dh %02dm %02ds", hours, mins, secs);
        }
        return String.format("%dm %02ds", mins, secs);
    }
}

