    @Override
    protected void startUp()
    {
        userKey = getOrCreateUserKey();

        // Populate patch registry instances
        // We define an ordered list so the panel shows patches in logical order.
        buildRegistry();

        // Load saved state from ConfigManager
        loadSavedState();

        // Build sidebar panel
        panel = new FarmNotifierPanel(this, config);
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/farming_icon.png");
        navButton = NavigationButton.builder()
                .tooltip("Farm Run Notifier")
                .icon(icon)
                .priority(6)
                .panel(panel)
                .build();
        clientToolbar.addNavigation(navButton);

        // Tick every second to update countdown labels and check warnings
        swingTimer = new javax.swing.Timer(1000, e -> onTick());
        swingTimer.start();

        log.info("Farm Run Notifier started. User key: {}", userKey);
    }

    @Override
    protected void shutDown()
    {
        if (swingTimer != null)
        {
            swingTimer.stop();
        }
        clientToolbar.removeNavigation(navButton);
        saveAllState();
        log.info("Farm Run Notifier stopped.");
    }

