    private void loadSavedState()
    {
        for (PatchState ps : patchRegistry.values())
        {
            String readyStr = configManager.getConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_ready");
            if (readyStr != null)
            {
                try { ps.readyAt = Long.parseLong(readyStr); } catch (NumberFormatException ignored) {}
            }
            String healthStr = configManager.getConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_health");
            if (healthStr != null)
            {
                try { ps.health = HealthStatus.valueOf(healthStr); } catch (IllegalArgumentException ignored) {}
            }
            String warnedStr = configManager.getConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_warned");
            ps.warningSent = "true".equals(warnedStr);
        }
    }

    private void savePatchState(PatchState ps)
    {
        if (ps.readyAt > 0)
        {
            configManager.setConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_ready", ps.readyAt);
            configManager.setConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_health", ps.health.name());
            configManager.setConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_warned", ps.warningSent);
        }
        else
        {
            configManager.unsetConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_ready");
            configManager.unsetConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_health");
            configManager.unsetConfiguration(CONFIG_GROUP, "p_" + ps.patchKey + "_warned");
        }
    }

    private void saveAllState()
    {
        for (PatchState ps : patchRegistry.values())
        {
            savePatchState(ps);
        }
    }

    // -------------------------------------------------------------------------
    // Chat message handling
    // -------------------------------------------------------------------------

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
                && type != ChatMessageType.MESBOX)
        {
            return;
        }

        String msg = event.getMessage().toLowerCase().replaceAll("<[^>]+>", "");

        // --- Planting detection ---
        if (msg.contains("you plant") || msg.contains("you pot the"))
        {
            FarmType ft = detectFarmType(msg);
            if (ft != null)
            {
                PatchState ps = findNearestPatch(ft);
                if (ps != null)
                {
                    startPatchTimer(ps);
                }
            }
        }

        // --- Harvest / clear detection ---
        else if (isHarvestMessage(msg))
        {
            // Try to detect farm type from message content
            FarmType ft = detectFarmType(msg);
            PatchState ps = null;
            if (ft != null)
            {
                ps = findNearestPatch(ft);
            }
            else
            {
                ps = findNearestActivePatch();
            }
            if (ps != null && ps.isActive())
            {
                clearPatchTimer(ps, true);
            }
        }

        // --- Health change detection ---
        else if (msg.contains("is diseased") || msg.contains("has become diseased"))
        {
            PatchState ps = findNearestActivePatch();
            if (ps != null)
            {
                updatePatchHealth(ps, HealthStatus.DISEASED);
            }
        }
        else if (msg.contains("has died") || msg.contains("the crop has died"))
        {
            PatchState ps = findNearestActivePatch();
            if (ps != null)
            {
                updatePatchHealth(ps, HealthStatus.DEAD);
                clearPatchTimer(ps, false);
            }
        }
        else if (msg.contains("has been cured") || msg.contains("is healthy")
                || msg.contains("growing well") || msg.contains("you cure"))
        {
            PatchState ps = findNearestActivePatch();
            if (ps != null && ps.health == HealthStatus.DISEASED)
            {
                updatePatchHealth(ps, HealthStatus.HEALTHY);
            }
        }
    }

    private boolean isHarvestMessage(String msg)
    {
        return msg.contains("you harvest")
                || msg.contains("you've cleared")
                || msg.contains("you clear the")
                || msg.contains("successfully completed")
                || msg.contains("the patch has been cleared");
    }

    // -------------------------------------------------------------------------
    // Periodic tick (every second via Swing timer)
    // -------------------------------------------------------------------------

    private void onTick()
    {
        long now = System.currentTimeMillis();

        for (PatchState ps : patchRegistry.values())
        {
            if (!ps.isActive()) continue;

            // Fire ready notification
            if (now >= ps.readyAt)
            {
                if (isNotifyEnabled(ps.farmType))
                {
                    boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
                    if (!config.notifyOnlyWhenLoggedOut() || !loggedIn)
                    {
                        sendDiscordWebhook(buildReadyMessage(ps));
                    }
                }
                clearPatchTimer(ps, false);
                continue;
            }

            // Fire warning notification (before ready)
            if (config.notifyBeforeReady() && !ps.warningSent)
            {
                long warningAt = ps.readyAt - (long) config.minutesBefore() * 60_000L;
                if (now >= warningAt)
                {
                    if (isNotifyEnabled(ps.farmType))
                    {
                        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
                        if (!config.notifyOnlyWhenLoggedOut() || !loggedIn)
                        {
                            sendDiscordWebhook(buildWarningMessage(ps));
                        }
                    }
                    ps.warningSent = true;
                    savePatchState(ps);
                    syncToFirebase();
                }
            }
        }

        // Update panel countdown labels
        SwingUtilities.invokeLater(() -> {
            if (panel != null) panel.refresh();
        });
    }

    // -------------------------------------------------------------------------
    // Timer management (public so panel can call them)
    // -------------------------------------------------------------------------

    public void startPatchTimer(PatchState ps)
    {
        long now = System.currentTimeMillis();
        ps.readyAt = now + (long) ps.farmType.getGrowthMinutes() * 60_000L;
        ps.health = HealthStatus.HEALTHY;
        ps.warningSent = false;
        savePatchState(ps);
        syncToFirebase();
        if (config.sendScreenshotOnPlant())
        {
            sendDiscordWebhookWithScreenshot(buildStartMessage(ps));
        }
        else
        {
            sendDiscordWebhook(buildStartMessage(ps));
        }
        log.info("Timer started: {} — ready in {} min", ps.displayName, ps.farmType.getGrowthMinutes());
    }

    public void clearPatchTimer(PatchState ps, boolean harvested)
    {
        log.info("Timer cleared: {} (harvested={})", ps.displayName, harvested);
        ps.readyAt = 0;
        ps.health = HealthStatus.HEALTHY;
        ps.warningSent = false;
        savePatchState(ps);
        syncToFirebase();
    }

    private void updatePatchHealth(PatchState ps, HealthStatus newHealth)
    {
        if (ps.health == newHealth) return;
        ps.health = newHealth;
        savePatchState(ps);
        syncToFirebase();

        String emoji = newHealth == HealthStatus.DISEASED ? "🤒" : "💀";
        String status = newHealth == HealthStatus.DISEASED ? "diseased" : "dead";
        sendDiscordWebhook(buildMention() + emoji + " **" + ps.displayName + "** is " + status + "!");
        log.info("Health update: {} → {}", ps.displayName, newHealth);
    }

    // -------------------------------------------------------------------------
    // Patch location helpers
    // -------------------------------------------------------------------------

    private PatchState findNearestPatch(FarmType type)
    {
        WorldPoint player = getPlayerLocation();
        if (player == null) return null;

        PatchState best = null;
        int bestDist = Integer.MAX_VALUE;

        for (Map.Entry<WorldPoint, String> entry : LOCATION_INDEX.entrySet())
        {
            PatchState ps = patchRegistry.get(entry.getValue());
            if (ps == null || ps.farmType != type) continue;

            int dist = player.distanceTo(entry.getKey());
            if (dist < bestDist && dist <= NEARBY_TILES)
            {
                bestDist = dist;
                best = ps;
            }
        }
        return best;
    }

    private PatchState findNearestActivePatch()
    {
        WorldPoint player = getPlayerLocation();
        if (player == null) return null;

        PatchState best = null;
        int bestDist = Integer.MAX_VALUE;

        for (Map.Entry<WorldPoint, String> entry : LOCATION_INDEX.entrySet())
        {
            PatchState ps = patchRegistry.get(entry.getValue());
            if (ps == null || !ps.isActive()) continue;

            int dist = player.distanceTo(entry.getKey());
            if (dist < bestDist && dist <= NEARBY_TILES)
            {
                bestDist = dist;
                best = ps;
            }
        }
        return best;
    }

    private WorldPoint getPlayerLocation()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return null;
        return client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
    }

