    private FarmType detectFarmType(String msg)
    {
        for (Map.Entry<String, FarmType> e : PLANT_KEYWORDS.entrySet())
        {
            if (msg.contains(e.getKey()))
            {
                return e.getValue();
            }
        }
        return null;
    }

