        return uid.isEmpty() ? "" : "<@" + uid + "> ";
    }

    private String buildStartMessage(PatchState ps)
    {
        return buildMention() + "🌱 **" + ps.displayName + "** planted — ready in "
                + ps.farmType.getGrowthMinutes() + " minutes.";
    }

    private String buildReadyMessage(PatchState ps)
    {
        return buildMention() + "🌿 **" + ps.displayName + "** is ready to harvest!";
    }

    private String buildWarningMessage(PatchState ps)
    {
        return buildMention() + "⏰ **" + ps.displayName + "** will be ready in "
                + config.minutesBefore() + " minutes.";
    }

    // -------------------------------------------------------------------------
    // Discord webhook
    // -------------------------------------------------------------------------

    /** Captures the next rendered game frame and sends it to Discord with the message. */
    private void sendDiscordWebhookWithScreenshot(String message)
    {
        String webhookUrl = config.webhookUrl().trim();
        if (webhookUrl.isEmpty()) return;

        drawManager.requestNextFrameListener(image ->
        {
            // Capture image bytes on the render thread — keep this fast, no network calls here
            byte[] imageBytes = null;
            try
            {
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ImageIO.write((RenderedImage) image, "png", baos);
                imageBytes = baos.toByteArray();
            }
            catch (Exception e)
            {
                log.warn("Failed to capture screenshot: {}", e.getMessage());
            }

            // Hand off to a background thread for the HTTP upload
            final byte[] finalBytes = imageBytes;
            new Thread(() ->
            {
                if (finalBytes == null)
                {
                    sendDiscordWebhook(message);
                    return;
                }
                try
                {
                    RequestBody multipart = new MultipartBody.Builder()
                            .setType(MultipartBody.FORM)
                            .addFormDataPart("payload_json", null,
                                    RequestBody.create(JSON_TYPE,
                                            "{\"content\":\"" + escapeJson(message) + "\"}"))
                            .addFormDataPart("file[0]", "farm_patch.png",
                                    RequestBody.create(MediaType.parse("image/png"), finalBytes))
                            .build();

                    Request request = new Request.Builder()
                            .url(webhookUrl)
                            .post(multipart)
                            .build();

                    try (Response response = okHttpClient.newCall(request).execute())
                    {
                        if (!response.isSuccessful())
                        {
                            log.warn("Discord screenshot webhook HTTP {} — falling back to text", response.code());
                            sendDiscordWebhook(message);
                        }
                    }
                }
                catch (Exception e)
                {
                    log.warn("Screenshot upload failed, sending text only: {}", e.getMessage());
                    sendDiscordWebhook(message);
                }
            }, "FarmNotifier-Screenshot-Upload").start();
        });
    }

    private void sendDiscordWebhook(String message)
    {
        String webhookUrl = config.webhookUrl().trim();
        if (webhookUrl.isEmpty()) return;

        new Thread(() -> {
            try
            {
                RequestBody body = RequestBody.create(JSON_TYPE,
                        "{\"content\":\"" + escapeJson(message) + "\"}");
                Request request = new Request.Builder()
                        .url(webhookUrl)
                        .post(body)
                        .build();
                try (Response response = okHttpClient.newCall(request).execute())
                {
                    if (!response.isSuccessful())
                    {
                        log.warn("Discord webhook returned HTTP {}", response.code());
                    }
                }
            }
            catch (Exception e)
            {
                log.warn("Failed to send Discord webhook: {}", e.getMessage());
            }
        }, "FarmNotifier-Discord").start();
    }

    // -------------------------------------------------------------------------
    // Firebase sync
    // -------------------------------------------------------------------------

    private static final MediaType JSON_TYPE = MediaType.parse("application/json; charset=utf-8");

    private void syncToFirebase()
    {
        String webhookUrl = config.webhookUrl().trim();
        if (webhookUrl.isEmpty()) return;

        // Snapshot active patches on the calling thread before handing off
        List<PatchState> active = new ArrayList<>();
        for (PatchState ps : patchRegistry.values())
        {
            if (ps.isActive()) active.add(ps);
        }

        final String webhookSnapshot = webhookUrl;
        final String discordUid      = config.discordUserId().trim();
        final int    notifyMins      = config.notifyBeforeReady() ? config.minutesBefore() : 0;

        new Thread(() -> {
            try
            {
                String url = "https://firestore.googleapis.com/v1/projects/" + FIREBASE_PROJECT_ID
                        + "/databases/(default)/documents/farmtimers/" + userKey;

                StringBuilder fields = new StringBuilder();
                fields.append("{\"fields\":{");
                appendStr(fields, "discord_webhook_url", webhookSnapshot);
                fields.append(",");
                appendStr(fields, "discord_user_id", discordUid);
                fields.append(",");
                appendInt(fields, "notify_minutes_before", notifyMins);

                for (PatchState ps : active)
                {
                    String k = "p_" + ps.patchKey;
                    fields.append(",");
                    appendInt(fields, k + "_ready", ps.readyAt);
                    fields.append(",");
                    appendStr(fields, k + "_health", ps.health.name());
                    fields.append(",");
                    appendBool(fields, k + "_warned", ps.warningSent);
                }
                fields.append("}}");

                RequestBody body = RequestBody.create(JSON_TYPE, fields.toString());
                Request request = new Request.Builder()
                        .url(url)
                        .patch(body)
                        .build();

                try (Response response = okHttpClient.newCall(request).execute())
                {
                    log.info("Firebase sync: HTTP {} ({} active patches)", response.code(), active.size());
                    if (!response.isSuccessful() && response.body() != null)
                    {
                        log.warn("Firebase sync error: {}", response.body().string());
                    }
                }
            }
            catch (Exception e)
            {
                log.warn("Firebase sync failed: {}", e.getMessage());
            }
        }, "FarmNotifier-Firebase").start();
    }

