    private String getOrCreateUserKey()
    {
        String key = configManager.getConfiguration(CONFIG_GROUP, "userKey");
        if (key == null || key.isEmpty())
        {
            key = UUID.randomUUID().toString();
            configManager.setConfiguration(CONFIG_GROUP, "userKey", key);
        }
        return key;
    }

    private static String escapeJson(String s)
    {
        return s.replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n")
                .replace("\r", "\\r");
    }

    private static void appendStr(StringBuilder sb, String key, String value)
    {
        sb.append("\"").append(key).append("\":{\"stringValue\":\"")
                .append(escapeJson(value)).append("\"}");
    }

    private static void appendInt(StringBuilder sb, String key, long value)
    {
        sb.append("\"").append(key).append("\":{\"integerValue\":\"")
                .append(value).append("\"}");
    }

    private static void appendBool(StringBuilder sb, String key, boolean value)
    {
        sb.append("\"").append(key).append("\":{\"booleanValue\":")
                .append(value).append("}");
    }

    private static void appendNull(StringBuilder sb, String key)
    {
        sb.append("\"").append(key).append("\":{\"nullValue\":null}");
    }

